const TCC_STATE={all:[],filtered:[],page:1,perPage:1000,word:""};
const FOLD=s=>(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const ESC=s=>(s||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const STOP=new Set("a o as os de da do das dos e em no na nos nas um uma uns umas para por com sem sobre entre ao aos à às seu sua seus suas que se como ou ano anos século seculo história historia estudo análise analise trabalho trabalhos curso tcc uma através atraves partir caso perspectivas considerações consideracoes breve importância importancia".split(" "));

function countsBy(key){return TCC_STATE.all.reduce((acc,x)=>{const v=x[key];acc[v]=(acc[v]||0)+1;return acc},{});}
function fillStats(){const years=countsBy("ano"), advisors=new Set(TCC_STATE.all.map(x=>x.orientador));const peak=Object.entries(years).sort((a,b)=>b[1]-a[1])[0];
  document.querySelector("#tccTotal").textContent=TCC_STATE.all.length;
  document.querySelector("#tccYears").textContent=Object.keys(years).length;
  document.querySelector("#tccAdvisors").textContent=advisors.size;
  document.querySelector("#tccPeak").textContent=`${peak[0]} · ${peak[1]}`;
}
function buildTimeline(){const counts=countsBy("ano"), years=Object.keys(counts).map(Number).sort((a,b)=>a-b), max=Math.max(...Object.values(counts));const chart=document.querySelector("#tccYearChart");
 chart.innerHTML=years.map(y=>`<button class="tcc-year-column" data-year="${y}" title="${counts[y]} TCCs em ${y}"><span>${counts[y]}</span><i style="height:${Math.max(10,counts[y]/max*100)}%"></i><small>${y}</small></button>`).join("");
 chart.querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>showYear(+b.dataset.year,b)));
 showYear(years[years.length-1],chart.lastElementChild);
}
function showYear(year,button){document.querySelectorAll(".tcc-year-column").forEach(x=>x.classList.remove("active"));button?.classList.add("active");const items=TCC_STATE.all.filter(x=>x.ano===year);const detail=document.querySelector("#tccYearDetail");
 detail.innerHTML=`<div><p class="eyebrow">${year}</p><h3>${items.length} ${items.length===1?"trabalho identificado":"trabalhos identificados"}</h3></div><div class="tcc-year-list">${items.slice(0,8).map(x=>`<button data-title="${ESC(x.titulo)}"><strong>${ESC(x.autor)}</strong><span>${ESC(x.titulo)}</span></button>`).join("")}${items.length>8?`<button class="year-more" data-open-year="${year}">Ver todos os ${items.length} trabalhos →</button>`:""}</div>`;
 detail.querySelectorAll("[data-title]").forEach(b=>b.addEventListener("click",()=>{document.querySelector("#tccSearch").value=b.dataset.title;applyFilters(true)}));
 detail.querySelector("[data-open-year]")?.addEventListener("click",()=>{document.querySelector("#tccYear").value=year;applyFilters(true)});
}
function wordFrequency(){const freq={};TCC_STATE.all.forEach(x=>FOLD(x.titulo).replace(/[^a-z0-9\s-]/g," ").split(/\s+/).forEach(w=>{if(w.length>3&&!STOP.has(w)&&!/^[0-9-]+$/.test(w))freq[w]=(freq[w]||0)+1}));return Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,55)}
function buildCloud(){const words=wordFrequency(),max=words[0][1],min=words[words.length-1][1];const cloud=document.querySelector("#tccWordCloud");cloud.innerHTML=words.map(([w,n],i)=>{const size=1+(n-min)/(max-min||1)*2;return `<button style="font-size:${size.toFixed(2)}rem" data-word="${w}" title="${n} títulos">${w}<small>${n}</small></button>`}).join("");cloud.querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{TCC_STATE.word=b.dataset.word;document.querySelector("#tccSearch").value=b.dataset.word;document.querySelector("#clearWord").hidden=false;applyFilters(true)}));
 document.querySelector("#clearWord").addEventListener("click",()=>{TCC_STATE.word="";document.querySelector("#tccSearch").value="";document.querySelector("#clearWord").hidden=true;applyFilters(true)});
}
function buildThemes(){const counts={};TCC_STATE.all.forEach(x=>x.temas.forEach(t=>counts[t]=(counts[t]||0)+1));const grid=document.querySelector("#tccThemeGrid");grid.innerHTML=Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([t,n])=>`<button data-theme="${ESC(t)}"><span>${n}</span><strong>${ESC(t)}</strong><small>Explorar trabalhos →</small></button>`).join("");grid.querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{document.querySelector("#tccTheme").value=b.dataset.theme;applyFilters(true)}));}
function populateFilters(){const years=[...new Set(TCC_STATE.all.map(x=>x.ano))].sort((a,b)=>b-a),advisors=[...new Set(TCC_STATE.all.map(x=>x.orientador))].sort((a,b)=>a.localeCompare(b,"pt-BR")),themes=[...new Set(TCC_STATE.all.flatMap(x=>x.temas))].sort();
 document.querySelector("#tccYear").insertAdjacentHTML("beforeend",years.map(x=>`<option>${x}</option>`).join(""));
 document.querySelector("#tccAdvisor").insertAdjacentHTML("beforeend",advisors.map(x=>`<option>${ESC(x)}</option>`).join(""));
 document.querySelector("#tccTheme").insertAdjacentHTML("beforeend",themes.map(x=>`<option>${ESC(x)}</option>`).join(""));}
function applyFilters(scroll=false){const q=FOLD(document.querySelector("#tccSearch").value.trim()),year=document.querySelector("#tccYear").value,advisor=document.querySelector("#tccAdvisor").value,theme=document.querySelector("#tccTheme").value;
 TCC_STATE.filtered=TCC_STATE.all.filter(x=>(!q||FOLD(`${x.autor} ${x.titulo} ${x.orientador}`).includes(q))&&(!year||String(x.ano)===year)&&(!advisor||x.orientador===advisor)&&(!theme||x.temas.includes(theme)));TCC_STATE.page=1;renderTable();renderActiveFilters(q,year,advisor,theme);if(scroll)document.querySelector("#catalogo").scrollIntoView({behavior:"smooth"});}
function renderActiveFilters(q,year,advisor,theme){const row=document.querySelector("#activeFilters"),parts=[];if(q)parts.push(`Busca: ${ESC(document.querySelector("#tccSearch").value)}`);if(year)parts.push(`Ano: ${year}`);if(advisor)parts.push(`Orientador: ${ESC(advisor)}`);if(theme)parts.push(`Tema: ${ESC(theme)}`);row.innerHTML=parts.map(x=>`<span>${x}</span>`).join("");}
function renderTable(){const start=(TCC_STATE.page-1)*TCC_STATE.perPage,items=TCC_STATE.filtered.slice(start,start+TCC_STATE.perPage),pages=Math.max(1,Math.ceil(TCC_STATE.filtered.length/TCC_STATE.perPage));
 document.querySelector("#resultsCount").textContent=`${TCC_STATE.filtered.length} ${TCC_STATE.filtered.length===1?"registro encontrado":"registros encontrados"}`;
 document.querySelector("#tccTableBody").innerHTML=items.length?items.map(x=>`<tr><td><strong>${x.ano}</strong></td><td>${ESC(x.autor)}</td><td>${ESC(x.titulo)}</td><td>${ESC(x.orientador)}</td></tr>`).join(""):`<tr><td colspan="4" class="tcc-empty">Nenhum TCC corresponde aos filtros selecionados.</td></tr>`;
 document.querySelector("#tccPageInfo").textContent=`Página ${TCC_STATE.page} de ${pages}`;document.querySelector("#tccPrev").disabled=TCC_STATE.page<=1;document.querySelector("#tccNext").disabled=TCC_STATE.page>=pages;}
function clearFilters(){document.querySelector("#tccSearch").value="";document.querySelector("#tccYear").value="";document.querySelector("#tccAdvisor").value="";document.querySelector("#tccTheme").value="";TCC_STATE.word="";document.querySelector("#clearWord").hidden=true;applyFilters();}
function initTCC(){TCC_STATE.all=[...TCC_DATA];TCC_STATE.filtered=[...TCC_STATE.all];fillStats();buildTimeline();buildCloud();buildThemes();populateFilters();renderTable();
 ["#tccYear","#tccAdvisor","#tccTheme"].forEach(s=>document.querySelector(s).addEventListener("change",()=>applyFilters()));document.querySelector("#tccSearch").addEventListener("input",()=>applyFilters());document.querySelector("#tccClear").addEventListener("click",clearFilters);
 document.querySelector("#tccPrev").addEventListener("click",()=>{if(TCC_STATE.page>1){TCC_STATE.page--;renderTable();document.querySelector("#catalogo").scrollIntoView({behavior:"smooth"})}});document.querySelector("#tccNext").addEventListener("click",()=>{const p=Math.ceil(TCC_STATE.filtered.length/TCC_STATE.perPage);if(TCC_STATE.page<p){TCC_STATE.page++;renderTable();document.querySelector("#catalogo").scrollIntoView({behavior:"smooth"})}});}
try{initTCC()}catch(err){console.error(err);document.querySelector("#resultsCount").textContent="Não foi possível carregar a base."}
